"""Build the compact 17D review gallery from measured evidence, without fetching assets."""
from pathlib import Path
import json, html

root = Path('docs/mission-17-evidence/final')
read = lambda name: json.loads((root / name).read_text())
captures = read('captures.json')
performance = read('performance-summary.json')
inventory = read('inventory.json')
soak = read('soak-30min.json')
assert soak['isThirtyMinuteTest'] and soak['wallSeconds'] >= 1800 and soak['nativeSpanSeconds'] >= 1800
names = {'isole-5m':'Arbre seul · 5 m','groupe-15m':'Plusieurs arbres · 15 m','groupe-40m':'Groupe · 40 m','lisiere-100m':'Lisière · 100 m','foret-lointaine':'Forêt lointaine','aerienne':'Vue du ciel','berge':'Berges','village':'Village','pente':'Pente boisée','sous-bois':'Sous-bois dense'}
options = ''.join(f'<option value="{k}">{v}</option>' for k,v in names.items())
movies = [('wind-calm','Vent puis calme M11','Atelier métrique, modèle commun au jeu. Retour au calme commandé après huit secondes.'),('profiles','Qualité → Éco → Équilibré','Boucle native, même caméra dans le pilote. Chaque profil dure six secondes.'),('calendar','Quatre saisons · diagnostic accéléré','Mars à décembre en dix-huit secondes. Accélération inscrite dans les pixels.'),('walk-summer','Marche · été','Extrait natif du test continu, avec son.'),('walk-storm','Marche · vent fort','Extrait natif du test continu, avec son.'),('walk-winter','Marche · hiver','Extrait natif du test continu, avec son.')]
videos=''.join(f'<article><h3>{label}</h3><video controls playsinline preload="none" poster="{id}.jpg" src="{id}.webm" aria-label="{label}"></video><p>{desc}</p><a href="{id}.webm">Ouvrir le WebM</a></article>' for id,label,desc in movies)
seasons=''.join(f'<figure><img loading="lazy" src="season-{id}.jpg" alt="Grand feuillu étalé en {label}"><figcaption>{label}</figcaption></figure>' for id,label in [('spring','printemps'),('summer','été'),('autumn','automne'),('winter','hiver')])
lods=''.join(f'<figure><img loading="lazy" src="lod-{i}.jpg" alt="Même arbre au LOD {i}"><figcaption>LOD {i} · caméra identique, niveau forcé</figcaption></figure>' for i in range(4))
profiles=''.join(f'<figure><img loading="lazy" src="profile-{id}.jpg" alt="Forêt en profil {label}"><figcaption>{label} · même caméra dans le pilote</figcaption></figure>' for id,label in [('eco','Éco'),('balanced','Équilibré'),('quality','Qualité')])
table=''.join('<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in [x['label'], '–'.join(map(str,x['heightRangeM']))+' m',*x['triangles'],x['flatNearTriangles']])+'</tr>' for x in inventory['familyRows'])
rows=performance['summary']
bench=[]
for campaign in ['colour','local-shadow']:
 for view in (['bois','aerienne','berge'] if campaign=='colour' else ['bois']):
  for profile in ['eco','balanced','quality']:
   cells=[next(x for x in rows if x['campaign']==campaign and x['id']==view and x['profile']==profile and x['version']==v) for v in ['m16','m17c','after']]
   bench.append({'campaign':campaign,'view':view,'profile':profile,'values':[{'version':v,'medianMs':c['medianMs'],'p95Ms':c['p95Ms'],'calls':c['calls'],'triangles':c['triangles']} for v,c in zip(['M16','17C','17D'],cells)]})
css='''*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#10251f;color:#f3f0df;font:16px/1.55 system-ui,sans-serif}main,header{max-width:1320px;margin:auto;padding:24px}header{border-bottom:1px solid #587865}h1{font:500 clamp(28px,4vw,48px)/1.15 Georgia,serif}h2{margin-top:42px;font:500 30px/1.2 Georgia,serif}h3{font-size:19px}a{color:#c0dcaa}nav{display:flex;flex-wrap:wrap;gap:20px}select,button{font:inherit;color:inherit;background:#264c3d;border:1px solid #829e84;border-radius:6px;padding:8px;max-width:100%}label{display:inline-block;margin:8px 18px 8px 0}figure{margin:0}figcaption{padding:9px 0;color:#cdd4bf}img,video{display:block;width:100%;height:auto;background:#173c30;border-radius:5px}video{aspect-ratio:3/2}.pair,.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.note{padding:16px;background:#233c30;border-left:4px solid #d4bb7e}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid #56715e;padding:8px;white-space:nowrap}.barrow{display:grid;grid-template-columns:55px minmax(0,1fr) 90px;align-items:center;gap:8px;margin:8px 0}.bar{height:24px;background:#93b887;border-radius:3px}.barrow:nth-child(2) .bar{background:#c4b079}.barrow:nth-child(3) .bar{background:#b1d6cc}#camera{overflow-wrap:anywhere}small{color:#c5cfbd}@media(max-width:650px){main,header{padding:16px}.pair,.grid,.three{grid-template-columns:1fr}h2{font-size:26px}}'''
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth — Mission 17D</title><style>CSS</style><header><p>ENDLESS EARTH · ANGLES-SUR-L’ANGLIN · REVUE 17D</p><h1>Des branches au paysage</h1><p>LOD, coût du rendu et trente minutes de marche. Branche de revue ; la fluidité sur GPU physique reste à valider.</p><nav><a href="#comparison">Avant / après</a><a href="#motion">Mouvement</a><a href="#library">Bibliothèque</a><a href="#performance">Mesures</a><a href="../../mission-17.md">Rapport complet</a></nav></header><main>
<section id="comparison"><h2>Trente comparaisons sans sélection flatteuse</h2><p>Même caméra, date et météo, Mission 16 et 17D. Tous les arbres du pilote sont conservés. Les cinq captures du propriétaire n’étaient pas jointes au texte reçu : ces stations ne sont pas des correspondances exactes revendiquées.</p><label>Situation <select id="scene">OPTIONS</select></label><label>Saison <select id="season"><option value="06">Été · 21 juin</option><option value="10">Automne · 18 octobre</option><option value="01">Hiver · 21 janvier</option></select></label><div class="pair"><figure><img id="before" src="isole-5m-06-m16.jpg" alt="Mission 16"><figcaption>Avant · Mission 16</figcaption></figure><figure><img id="after" src="isole-5m-06-after.jpg" alt="Mission 17D"><figcaption>Après · Mission 17D</figcaption></figure></div><p id="camera"></p><p><a href="captures.json">Positions et protocole</a>. À cinq mètres, le cadrage coupe volontairement la haute couronne. La vue lointaine est une caméra de revue. Des pousses planes restent perceptibles aux niveaux les plus économiques.</p></section>
<section id="motion"><h2>Le mouvement à sa cadence native</h2><p class="note">SwiftShader est un GPU logiciel. Ces films conservent ses images lentes et ses à-coups. Seul le diagnostic du calendrier accélère les saisons. Aucun filtrage de vitesse, interpolation ou replay du vent.</p><div class="grid">VIDEOS</div><p>SOAK</p><p><a href="movies.json">Métadonnées des films</a> · <a href="soak-30min.json">Test prolongé</a> · <a href="soak-trace.json.gz">Trace par image</a></p></section>
<section id="library"><h2>Silhouettes, saisons et simplification</h2><p>Onze familles tempérées génériques créées procéduralement. L’atelier métrique montre les modèles du jeu ; il ne décrit aucun arbre relevé sur place. Le verger reste une forme de bibliothèque, sans individu ajouté dans le pilote.</p><img loading="lazy" src="library.jpg" alt="Onze familles à une échelle métrique commune"><div class="grid">SEASONS</div><h3>Même arbre, même caméra, quatre niveaux forcés</h3><div class="grid">LODS</div><p>Ces vues révèlent le changement de représentation ; le jeu sélectionne normalement les niveaux selon leur taille projetée et applique un fondu de 0,48 s. Les plans de feuillage sont distribués dans la couronne tridimensionnelle.</p><h3>Trois profils dans le pilote</h3><div class="grid three">PROFILES</div><div class="scroll"><table><thead><tr><th>Famille</th><th>Plage générique</th><th>LOD 0</th><th>LOD 1</th><th>LOD 2</th><th>LOD 3</th><th>LOD 0 aplati</th></tr></thead><tbody>TABLE</tbody></table></div><p>Triangles par modèle source. Les tailles individuelles sont calibrées séparément. <a href="inventory.json">Inventaire et politiques</a> · <a href="../sources.json">Provenance artistique et licences</a> · <a href="../../../public/data/LICENSE.md">Sources géographiques</a>.</p></section>
<section id="performance"><h2>Comparer le coût, conserver les réserves</h2><p>432 rendus GPU synchronisés, Chromium SwiftShader logiciel, 960 × 640, DPR 1. Douze échantillons chauds alternés par cellule, caméra et climat identiques. La série « ombre locale » mesure une carte stable, sans forcer son recalcul.</p><label>Campagne <select id="campaign"><option value="colour">Couleur seule</option><option value="local-shadow">Ombre locale stable</option></select></label><label>Vue <select id="view"><option value="bois">Bois</option><option value="aerienne">Aérienne</option><option value="berge">Berges</option></select></label><label>Profil <select id="profile"><option value="eco">Éco</option><option value="balanced" selected>Équilibré</option><option value="quality">Qualité</option></select></label><div id="bars" aria-live="polite"></div><p id="numbers"></p><p>La comparaison avec 17C montre l’effet des optimisations. Le surcoût restant face à Mission 16 empêche de considérer la fluidité comme acquise. Aucun FPS de téléphone ou de GPU physique n’est déduit de cette campagne.</p><p><a href="performance-summary.json">Médianes, P95, pics, appels, textures et allocations</a> · <a href="performance.json.gz">432 mesures</a> · <a href="costs.json">Vent et recalcul des ombres</a> · <a href="validation.json">Mémoire, streaming et replis de cache</a> · <a href="preservation.json">Préservation des sources et archives</a></p></section></main><script>DATA
const $=id=>document.getElementById(id);function compare(){const id=$('scene').value,month=$('season').value;for(const [name,v]of [['before','m16'],['after','after']])$(name).src=id+'-'+month+'-'+v+'.jpg';const s=scenes.find(s=>s.id===id);$('camera').textContent='Station : '+s.v.slice(1,3).map(x=>x.toFixed(3)).join(' / ')+' m en coordonnées locales'+(s.camera?' · caméra '+s.camera.map(x=>x.toFixed(3)).join(' / '):' · pose de jeu enregistrée')+'.'}function chart(){const shadow=$('campaign').value==='local-shadow';$('view').disabled=shadow;if(shadow)$('view').value='bois';const r=bench.find(x=>x.campaign===$('campaign').value&&x.view===$('view').value&&x.profile===$('profile').value),max=Math.max(...r.values.map(x=>x.medianMs));$('bars').innerHTML=r.values.map(x=>'<div class="barrow"><span>'+x.version+'</span><div class="bar" style="width:'+Math.max(1,x.medianMs/max*100)+'%"></div><span>'+x.medianMs.toFixed(1)+' ms</span></div>').join('');$('numbers').textContent=r.values.map(x=>x.version+' : P95 '+x.p95Ms.toFixed(1)+' ms, '+x.calls+' appels, '+Math.round(x.triangles).toLocaleString('fr-FR')+' triangles').join(' · ');}for(const id of ['scene','season'])$(id).addEventListener('change',compare);for(const id of ['campaign','view','profile'])$(id).addEventListener('change',chart);compare();chart();</script></html>'''
summary=f"{soak['wallSeconds']/60:.2f} minutes murales, {soak['nativeSpanSeconds']/60:.2f} minutes de frames natives, {soak['metres']:.1f} m parcourus, {soak['frameCount']} images. Intervalles : médiane {soak['intervalMs']['median']:.1f} ms, P95 {soak['intervalMs']['p95']:.1f} ms, pointe {soak['intervalMs']['peak']:.1f} ms. Ces chiffres décrivent la stabilité technique et la lenteur du rendu logiciel."
for key,value in [('CSS',css),('OPTIONS',options),('VIDEOS',videos),('SOAK',summary),('SEASONS',seasons),('LODS',lods),('PROFILES',profiles),('TABLE',table),('DATA','const scenes='+json.dumps(captures['scenes'])+';const bench='+json.dumps(bench)+';')]:page=page.replace(key,value)
(root/'index.html').write_text(page)
print('Wrote 17D gallery with 30 pairs, 6 native movies, four seasons/LODs and measured comparisons')
